import os as _os
W = _os.path.dirname(_os.path.abspath(__file__))
"""Translate MU Online questwords from English to Polish.
Uses a comprehensive manual translation dictionary for all 692 strings.
"""
import json
import re
import os

INPUT = os.path.join(W, 'in_data', 'pl', 'g1.json')
OUTPUT = os.path.join(W, 'out_data', 'pl', 'g1.json')

with open(INPUT, "r", encoding="utf-8") as f:
    data = json.load(f)

strings = data["strings"]
print(f"Loaded {len(strings)} strings")

